class DB {
  late SharedPreferences p;
  List<Map<String,dynamic>> items=[], customers=[], rentals=[];
  Future<void> load() async { p=await SharedPreferences.getInstance(); items=read('items'); customers=read('customers'); rentals=read('rentals'); }
  List<Map<String,dynamic>> read(String k){ final s=p.getString(k); if(s==null)return []; return (jsonDecode(s) as List).map((e)=>Map<String,dynamic>.from(e)).toList(); }
  Future<void> save() async { await p.setString('items',jsonEncode(items)); await p.setString('customers',jsonEncode(customers)); await p.setString('rentals',jsonEncode(rentals)); }
  String id()=>DateTime.now().microsecondsSinceEpoch.toString();
}

class Shell extends StatefulWidget { const Shell({super.key}); @override State<Shell> createState()=>_ShellState(); }
class _ShellState extends State<Shell>{
  final db=DB(); int tab=0; bool loading=true; DateTime? lastBack;
  @override void initState(){super.initState(); init();}
  Future<void> init()async{await Future.wait([db.load(),Future.delayed(const Duration(milliseconds:1400))]);if(mounted)setState(()=>loading=false);}
  void refresh()=>setState((){});
  Future<void> handleBack() async {
    if(tab!=0){setState(()=>tab=0);return;}
    final now=DateTime.now();
    if(lastBack!=null && now.difference(lastBack!)<const Duration(seconds:2)){return;}
    lastBack=now;
    if(!mounted)return;
    ScaffoldMessenger.of(context).hideCurrentSnackBar();
    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Press back again to exit'),duration:Duration(seconds:2)));
  }
  @override Widget build(BuildContext c){
    if(loading)return const Splash();
    final pages=[Home(db,refresh,(i)=>setState(()=>tab=i)),Items(db,refresh),Customers(db,refresh),Reports(db)];
    return PopScope(
      canPop:false,
      onPopInvokedWithResult:(didPop,result){if(!didPop)handleBack();},
      child:Scaffold(
        body:IndexedStack(index:tab,children:pages),
        bottomNavigationBar:NavigationBar(height:72,backgroundColor:Colors.white,indicatorColor:mint,selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[
          NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home_rounded),label:'Home'),
          NavigationDestination(icon:Icon(Icons.inventory_2_outlined),selectedIcon:Icon(Icons.inventory_2_rounded),label:'Items'),
          NavigationDestination(icon:Icon(Icons.people_outline),selectedIcon:Icon(Icons.people_rounded),label:'Customers'),
          NavigationDestination(icon:Icon(Icons.analytics_outlined),selectedIcon:Icon(Icons.analytics_rounded),label:'Reports')
        ]),
      ),
    );
  }
}

